/* Für [[Vorlage:Vorlagenbox]] */
.vorlagenbox {
	margin: -1px 10%;
	border-collapse: collapse;
	border: 1px solid #aaaaaa;
	/* {{Vorlagenbox|Typ=Notiz}} */
	border-left: 1em solid #608EC2;
	background: #fbfcff;
}

.vorlagenbox-Textgestaltung {
	border: none;
	padding: 0.25em 0.9em;
	width: 100%;
}
.vorlagenbox-Kein_Bild {
	border: none;
	padding: 0;
	width: 1px;
}
.vorlagenbox-Bild_links {
	border: none;
	padding: 2px 2px 2px 0.9em;
	text-align: center;
}
.vorlagenbox-Bildplatzhalter {
	width: 45px;
}
.vorlagenbox-Bild_rechts {
	border: none;
	padding: 2px 2px 2px 0px;
	text-align: center;
}

.vorlagenbox-Warnung {
	border-left: 1em solid #b22222;
}

.vorlagenbox-Hinweis {
	border-left: 1em solid #f57900;
}

.vorlagenbox-Auszeichnung {
	border-left: 1em solid #cba135;
	background: #fcf4dc;
}

.vorlagenbox-Nuetzlich {
	border-left: 1em solid #73d216;
}

.vorlagenbox-Gesperrt {
	border-left: 1em solid #bbbbaa;
}

.vorlagenbox-Lizenz {
	border-left: 1em solid #8888aa;
	background: #e1e1ea;
}

.vorlagenbox-Rechtlich {
	border-left: 1em solid #666666;
